<?php
/**
 * Blockive Premium Addon For Block Pro license manager.
 *
 * Talks to the Smart Licenser REST API at https://account.mveous.com/wp-json/sml/v1 to activate,
 * deactivate, and check for updates to this plugin. Generated by Smart
 * Licenser's Script Generator — safe to customize, but keep the REST
 * calls pointed at your licensing server.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

class Bpafb_Manager {

	const LICENSE_SERVER = 'https://account.mveous.com/wp-json/sml/v1';
	const PRODUCT_SLUG   = 'blockive-premium-addon-for-block-pro';
	const OPTION_KEY      = 'blockive_premium_addon_for_block_pro_license_key';

	// Set only if this product has a Request Encryption key configured
	// in Smart Licenser. When non-empty, every request below is sent
	// as an AES-256-GCM encrypted payload instead of plain fields, and
	// an encrypted response (Secure Update-Encrypted) is decrypted
	// transparently — see post() below.
	const REQUEST_ENCRYPTION_KEY = '/Tl0ysu5NG6z7EqWV56WAY8HdjlRIOEVxPes7j55jjc=';

	/**
	 * Why the last server call failed, in plain words ('' if it didn't).
	 * Shown on the license screen so a failed activation says what went
	 * wrong instead of just "could not reach the server".
	 */
	private string $last_error = '';

	private static ?Bpafb_Manager $instance = null;

	public static function instance(): Bpafb_Manager {
		if ( null === self::$instance ) {
			self::$instance = new self();
		}
		return self::$instance;
	}

	public static function get_instance(): Bpafb_Manager {
		return self::instance();
	}

	public function __construct() {
		// Plugin update hooks; left out for themes, which use a theme updater instead.
		add_filter( 'pre_set_site_transient_update_plugins', array( $this, 'check_for_update' ) );
		add_filter( 'plugins_api', array( $this, 'plugin_info' ), 10, 3 );
	}

	public function is_licensed(): bool {
		return '' !== $this->license_key();
	}

	private function license_key(): string {
		return (string) get_option( self::OPTION_KEY, '' );
	}

	public function last_error(): string {
		return $this->last_error;
	}

	/**
	 * The stored key with its middle hidden (ABCD-••••-••••-••••-WXYZ),
	 * safe to show on screen.
	 */
	public function masked_key(): string {
		$key = $this->license_key();

		if ( strlen( $key ) <= 8 ) {
			return '' === $key ? '' : str_repeat( '•', strlen( $key ) );
		}

		return substr( $key, 0, 4 ) . str_repeat( '•', max( 4, strlen( $key ) - 8 ) ) . substr( $key, -4 );
	}

	public function site_domain(): string {
		return $this->domain();
	}

	/**
	 * What the license server currently says about the stored key
	 * (status, expiry...). Cached for an hour so opening the license
	 * screen doesn't hit the server every time; $refresh bypasses it.
	 *
	 * @return array<string,mixed>|null Null if not licensed or the server couldn't be reached.
	 */
	public function details( bool $refresh = false ): ?array {
		if ( ! $this->is_licensed() ) {
			return null;
		}

		$cache_key = self::OPTION_KEY . '_details';
		$cached    = $refresh ? false : get_transient( $cache_key );

		if ( is_array( $cached ) ) {
			return $cached;
		}

		$data = $this->post(
			'/validate',
			array(
				'license_key' => $this->license_key(),
				'domain'      => $this->domain(),
				'product'     => self::PRODUCT_SLUG,
			)
		);

		if ( null !== $data ) {
			set_transient( $cache_key, $data, HOUR_IN_SECONDS );
		}

		return $data;
	}

	private function domain(): string {
		return (string) wp_parse_url( home_url(), PHP_URL_HOST );
	}

	/**
	 * @return array{valid?:bool,code?:string,message?:string}
	 */
	public function activate( string $key ): array {
		$response = $this->post(
			'/validate',
			array(
				'license_key' => $key,
				'domain'      => $this->domain(),
				'product'     => self::PRODUCT_SLUG,
			)
		);

		if ( $response && ! empty( $response['valid'] ) ) {
			update_option( self::OPTION_KEY, $key );
			set_transient( self::OPTION_KEY . '_details', $response, HOUR_IN_SECONDS );
		}

		return $response ?? array(
			'valid'   => false,
			'message' => '' !== $this->last_error
				/* translators: %s: technical reason the server call failed */
				? sprintf( __( 'Could not reach the license server (%s).', 'blockive-premium-addon-for-block-pro' ), $this->last_error )
				: __( 'Could not reach the license server.', 'blockive-premium-addon-for-block-pro' ),
		);
	}

	public function deactivate(): void {
		$key = $this->license_key();

		if ( '' === $key ) {
			return;
		}

		$this->post(
			'/deactivate',
			array(
				'license_key' => $key,
				'domain'      => $this->domain(),
				'product'     => self::PRODUCT_SLUG,
			)
		);

		delete_option( self::OPTION_KEY );
		delete_transient( self::OPTION_KEY . '_details' );
	}

	/**
	 * If REQUEST_ENCRYPTION_KEY is set, $body is sent as a single
	 * AES-256-GCM `encrypted` field (plus `product`, needed for the
	 * server to find the right key) instead of its plain fields, and a
	 * response shaped {"encrypted": "..."} is decrypted back into the
	 * plain array transparently — every caller below gets the same
	 * plain-array shape either way.
	 */
	private function post( string $path, array $body ): ?array {
		$encrypted_body = $this->encrypt_payload( $body );

		if ( null !== $encrypted_body ) {
			$body = array(
				'product'   => $body['product'] ?? self::PRODUCT_SLUG,
				'encrypted' => $encrypted_body,
			);
		}

		$response = wp_remote_post(
			self::LICENSE_SERVER . $path,
			array(
				'timeout' => 15,
				'body'    => $body,
			)
		);

		$this->last_error = '';

		if ( is_wp_error( $response ) ) {
			$this->last_error = $response->get_error_message();
			return null;
		}

		$data = json_decode( wp_remote_retrieve_body( $response ), true );

		if ( ! is_array( $data ) ) {
			/* translators: %d: HTTP status code */
			$this->last_error = sprintf( __( 'the server answered with HTTP %d and not a license response', 'blockive-premium-addon-for-block-pro' ), (int) wp_remote_retrieve_response_code( $response ) );
			return null;
		}

		if ( isset( $data['encrypted'] ) && is_string( $data['encrypted'] ) ) {
			$decrypted = $this->decrypt_payload( $data['encrypted'] );
			return $decrypted ?? $data;
		}

		return $data;
	}

	/**
	 * @param array<string,mixed> $data
	 */
	private function encrypt_payload( array $data ): ?string {
		if ( '' === self::REQUEST_ENCRYPTION_KEY || ! function_exists( 'openssl_encrypt' ) ) {
			return null;
		}

		$key = base64_decode( self::REQUEST_ENCRYPTION_KEY, true );

		if ( false === $key || 32 !== strlen( $key ) ) {
			return null;
		}

		$iv  = random_bytes( 12 );
		$tag = '';

		$ciphertext = openssl_encrypt( (string) wp_json_encode( $data ), 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag );

		return false !== $ciphertext ? base64_encode( $iv . $tag . $ciphertext ) : null;
	}

	/**
	 * @return array<string,mixed>|null
	 */
	private function decrypt_payload( string $payload ): ?array {
		if ( '' === self::REQUEST_ENCRYPTION_KEY || ! function_exists( 'openssl_decrypt' ) ) {
			return null;
		}

		$key = base64_decode( self::REQUEST_ENCRYPTION_KEY, true );

		if ( false === $key || 32 !== strlen( $key ) ) {
			return null;
		}

		$raw = base64_decode( $payload, true );

		if ( false === $raw || strlen( $raw ) <= 28 ) {
			return null;
		}

		$plaintext = openssl_decrypt( substr( $raw, 28 ), 'aes-256-gcm', $key, OPENSSL_RAW_DATA, substr( $raw, 0, 12 ), substr( $raw, 12, 16 ) );

		if ( false === $plaintext ) {
			return null;
		}

		$data = json_decode( $plaintext, true );

		return is_array( $data ) ? $data : null;
	}

	private function current_version(): string {
		return BPAFB_PRO_VERSION;
	}

	/**
	 * What the server says about updates for the stored license
	 * (valid, update_available, version, download_url...). Used by the
	 * theme updater; plugins use the filters in the constructor.
	 *
	 * @return array<string,mixed>|null
	 */
	public function update_info(): ?array {
		return $this->update_check_request();
	}

	private function update_check_request(): ?array {
		if ( ! $this->is_licensed() ) {
			return null;
		}

		return $this->post(
			'/update-check',
			array(
				'license_key' => $this->license_key(),
				'domain'      => $this->domain(),
				'product'     => self::PRODUCT_SLUG,
				'version'     => $this->current_version(),
			)
		);
	}

	public function check_for_update( $transient ) {
		if ( empty( $transient->checked ) ) {
			return $transient;
		}

		$data = $this->update_check_request();

		if ( ! $data || empty( $data['valid'] ) || empty( $data['update_available'] ) ) {
			return $transient;
		}

		$plugin_file = plugin_basename( BLOCKIVE_PREMIUM_ADDON_FOR_BLOCK_PRO_PLUGIN_FILE );

		$transient->response[ $plugin_file ] = (object) array(
			'slug'         => self::PRODUCT_SLUG,
			'plugin'       => $plugin_file,
			'new_version'  => $data['version'],
			'url'          => home_url(),
			'package'      => $data['download_url'] ?? '',
			'tested'       => $data['tested'] ?? '',
			'requires'     => $data['requires'] ?? '',
			'requires_php' => $data['requires_php'] ?? '',
		);

		return $transient;
	}

	public function plugin_info( $result, $action, $args ) {
		if ( 'plugin_information' !== $action || empty( $args->slug ) || self::PRODUCT_SLUG !== $args->slug ) {
			return $result;
		}

		$data = $this->update_check_request();

		if ( ! $data || empty( $data['valid'] ) ) {
			return $result;
		}

		return (object) array(
			'name'         => 'Blockive Premium Addon For Block Pro',
			'slug'         => self::PRODUCT_SLUG,
			'version'      => $data['version'] ?? '1.0.1',
			'tested'       => $data['tested'] ?? '',
			'requires'     => $data['requires'] ?? '',
			'requires_php' => $data['requires_php'] ?? '',
			'sections'     => array( 'changelog' => wpautop( $data['changelog'] ?? '' ) ),
		);
	}
}
